{
  "qa": [
    {
      "question": "停车场管理中如何确保外来车辆不会长期滞留导致僵尸车问题？",
      "answer": "停车场对长期滞留的车辆会通过车主电话联系或114查询方式要求车主在24小时内驶离，且外来车辆超过一天将被清理，以避免形成僵尸车。"
    },
    {
      "question": "公司对进出停车场的外部人员有哪些管理规定？",
      "answer": "外部人员需登记来访目的、时间及预计停留时长，超过一天者将被清理，以防止因无住宿条件导致的滞留。"
    },
    {
      "question": "停车场监控系统是否完善且需要更新？",
      "answer": "停车场监控系统覆盖全面且无死角，最近两个月已更新设备，画面清晰度高，目前运行状况良好。"
    }
  ]
}
